insert into public.content_items (id, source, wordpress_post_id, canonical_url, title, excerpt, destination_id, topic) values
  ('wp-2143', 'wordpress', 2143, 'https://comemorocco.com/sahara-desert-tours-morocco-guide/', 'Ultimate Guide to Sahara Desert Tours Morocco 2025 How to Choose the Best Experience', 'Discover how to choose the best Sahara Desert tours Morocco offers. Compare Morocco desert trips, top Sahara camel tours, and expert tips for an unforgettable adventure', 'merzouga', 'Activities'),
  ('wp-2274', 'wordpress', 2274, 'https://comemorocco.com/moroccan-festivals-2025-guide/', '10 Unmissable Moroccan Festivals 2026: Ultimate Guide to Culture and Events', 'Discover the best Moroccan festivals and events 2024. Enjoy vibrant culture, travel tips, and must-see celebrations across Morocco.', 'fes', 'Culture'),
  ('wp-2295', 'wordpress', 2295, 'https://comemorocco.com/food-tours-marrakech-ultimate-guide/', 'Ultimate Guide to Food Tours Marrakech for Authentic Cuisine', 'Discover the best food tours Marrakech offers. Explore markets, taste authentic Moroccan dishes, and enjoy insider tips for an unforgettable journey', 'marrakech', 'Food'),
  ('wp-2306', 'wordpress', 2306, 'https://comemorocco.com/ancient-cities-morocco-historical-treasures/', '7 Breathtaking Ancient Cities Morocco: Ultimate Explorer''s Guide', 'Discover 7 breathtaking ancient cities Morocco offers, from Fes to Marrakech. Explore Morocco historical cities and old towns with our ultimate guide to North Africa''s living treasures.', 'marrakech', 'Food'),
  ('wp-2356', 'wordpress', 2356, 'https://comemorocco.com/religious-festivals-morocco-guide/', 'Religious Festivals Morocco Ultimate Guide to Celebrations', 'Discover religious festivals Morocco from Eid to local moussems. Explore Morocco religious holidays, Islamic festivals, and Eid traditions in this guide', 'fes', 'Culture'),
  ('wp-2358', 'wordpress', 2358, 'https://comemorocco.com/religion-in-morocco-guide/', 'The Ultimate Guide to Religion in Morocco for Travelers 2025', 'Discover the rich religion in Morocco, explore iconic Morocco mosques, vibrant religious festivals, and experience Morocco''s unique religious culture and Islam traditions.', 'fes', 'Culture'),
  ('wp-2452', 'wordpress', 2452, 'https://comemorocco.com/morocco-safety-travel-guide-2025/', 'Morocco Safety 2025 Essential Travel Tips and Complete Guide', 'Discover essential Morocco safety tips for 2025. Learn how to stay safe, avoid scams, and enjoy secure travel in Marrakech, Casablanca, and beyond', 'marrakech', 'Safety'),
  ('wp-2457', 'wordpress', 2457, 'https://comemorocco.com/moroccan-markets-shopping-guide/', '10 Best Moroccan Markets Guide: Ultimate Souk Shopping Tips', 'Discover the ultimate Moroccan markets guide with tips on shopping in Moroccan markets and souks, what to buy, how to haggle, and must-visit spots.', 'marrakech', 'Food'),
  ('wp-2501', 'wordpress', 2501, 'https://comemorocco.com/couples-activities-morocco-romance/', '15 Unforgettable Couples Activities Morocco Offers for Romantic Getaways', 'Discover 15 unforgettable couples activities Morocco offers, from desert treks to romantic riads, perfect for honeymoons, anniversaries, or dreamy getaways.', 'merzouga', 'Accommodation'),
  ('wp-2826', 'wordpress', 2826, 'https://comemorocco.com/where-to-stay-in-marrakech/', 'Where to Stay in Marrakech: 15 Coolest Riads', 'Deciding where to stay in Marrakech? This guide reveals the 15 coolest riads for every budget. Find your perfect authentic Moroccan stay, from luxe to cheap.', 'marrakech', 'Accommodation'),
  ('wp-2833', 'wordpress', 2833, 'https://comemorocco.com/marrakech-hotels-guide-2025/', 'Marrakech Hotels 2025: Ultimate Luxury Stay Guide', 'Compare Marrakech hotels for 2025—discover top areas, Four Seasons Marrakech perks, insider tips & prices for unforgettable Marrakech luxury travel', 'marrakech', 'Accommodation'),
  ('wp-2841', 'wordpress', 2841, 'https://comemorocco.com/where-to-stay-in-marrakech-2/', 'Where to Stay in Marrakech: 9 Epic Areas & Hotels Guide', 'Wondering where to stay in Marrakech? Discover the coolest riads, top Marrakech hotels like Four Seasons, plus pro luxury travel tips.', 'marrakech', 'Accommodation'),
  ('wp-2875', 'wordpress', 2875, 'https://comemorocco.com/affordable-riads-in-marrakech-budget/', '15 Best Affordable Riads in Marrakech: Experience Authentic Morocco on a Budget', 'Discover the best affordable riads in Marrakech. Our guide to budget-friendly accommodation Marrakech features top-rated, authentic riads under $100/night for an unforgettable Moroccan experience.', 'marrakech', 'Accommodation'),
  ('wp-2989', 'wordpress', 2989, 'https://comemorocco.com/luxury-hotels-marrakech-medina/', 'Unforgettable Stays: Your Guide to Luxury Hotels in Marrakech Medina (Updated 2025)', 'Updated 2025 guide to the best luxury hotels Marrakech Medina! Find 5-star stays, riads, & maybe an all-inclusive option. Book your unforgettable Moroccan escape!', 'marrakech', 'Accommodation'),
